namespace BoatsNBeasts.Core;

public static partial class FarLedger
{
    static CampaignArc Saltstep() => CampaignArc.Create("The Saltstep Terraces", "The Gardens Put Out Feet",
        "The first island to leave pulls six wet roots out of Last Light’s steps. Under each one is a sea snail the size of a rice grain. Uma Pike puts five in a jar and waits for the sixth to choose where to go.",
        "Uma’s folding tide spoon with the depth scratched into its bowl",
        new("Uma Pike  /  pool botanist",
            "Who gets to decide which garden travels?",
            "One terrace has already crossed a channel on its own roots. Uma can take cuttings to reassure the growers who depend on it, or put the growers aboard with their orchard. There is one deck of free space.",
            "Carry the root library",
            "Carry the gardeners",
            "The pots stand in a wet blanket. Uma writes the name of each person who entrusted her with a cutting on its saucer.",
            "Four gardeners throw their boots ashore. Their feet can tell mature soil from hungry mud while the roots move."),
        9,
        [
            Crossing("wake-salt-foot", SeaDuty.Sounding, "The Step Under the Step",
                "Uma hears running water below a staircase that has stood dry for forty years. At dawn the staircase is three yards to the east, carrying a brown hen and its nest.",
                "Sound the warm pits under the salt stairs.", "Spade Skate",
                "Lio draws toes on the chart. Uma corrects the number of toes and leaves the drawing.", 7, SeaJob.Sound, SeaJob.Track, SeaJob.Relay),
            Landfall("wake-salt-root", "The Bent Nursery",
                "The head gardener tied her terrace to the bedrock when the first roots started walking. Every bean plant is now lying across its own row.", "Cotyledon Drake",
                "The terrace straightens. Its first free step leaves a pool full of white roots. Uma fills her old measuring spoon.", 7,
                At(LandingAction.Haul, YardSite.West, "Tie stone", "Lift the tie stone clear of the young roots"),
                At(LandingAction.Cut, YardSite.East, "Root braid", "Cut the gardener’s braid above its graft"),
                At(LandingAction.Guide, YardSite.Stairs, "Head gardener", "Walk the gardener to her moving terrace")),
            Crossing("wake-salt-library", SeaDuty.Convoy, "A Deck of Little Countries",
                "Each flowerpot needs a cup of water from its own terrace. Lio has labeled the buckets by smell. Nell asks for a second system.",
                "Bring the living root library across the dry reach.", "Saucer Squid",
                "The smallest pot puts out a root and catches hold of Lio’s sleeve. He has to write his labels with the other hand.", 8, SeaJob.Tow, SeaJob.Relieve, SeaJob.Guide),
            Landfall("wake-salt-heel", "The Heel Bed",
                "A grandparent island has stopped halfway across a mussel farm. It has a numbered survey nail in its heel. Uma recognizes the number from her first summer in the field.", "Survey Nail Borer",
                "Uma wraps the old nail in its survey drawing and gives it to the mussel farmer. He marks the depth of the healing print on her tide spoon.", 7,
                At(LandingAction.Brace, YardSite.West, "Heel cradle", "Brace the heel before Lio takes the strain"),
                At(LandingAction.Haul, YardSite.Fallen, "Survey nail", "Draw the nail in the direction it entered"),
                At(LandingAction.Seat, YardSite.East, "Clean graft", "Seat a clean graft in the heel scar")),
            Crossing("wake-salt-saucer", SeaDuty.Salvage, "The First Herbarium",
                "Uma once preserved a whole terrace by pressing it flat between two boards. A single tide pool is still wriggling on the last page of the lost collection.",
                "Raise the herbarium and carry its live page at water level.", "Blotter Ray",
                "A tiny terrace steps out of the book. Uma tears out the accession page and folds it into a little shade awning.", 8, SeaJob.Track, SeaJob.Salvage, SeaJob.Unload),
            Crossing("wake-salt-road", SeaDuty.Sounding, "Prints Toward Morning",
                "The islands do not walk toward the warmest water. They walk toward the puddles where other islands once stood. Uma wants a chart a child can use from the height of a beach bucket.",
                "Follow the fresh prints to the first safe sleeping bank.", "Spoonbill Lantern",
                "The growers print their departing island in mud on the harbor wall. Its next footprint appears beyond the Waxwing Roads.", 8, SeaJob.Sound, SeaJob.Relay, SeaJob.Guide)
        ],
        Crossing("wake-salt-feet", SeaDuty.Convoy, "Gardeners Aboard",
            "Four barefoot gardeners can feel the roots turning under the hull. Each calls a different direction. Lio realizes they are describing different feet.",
            "Escort the growers to the terrace that selected them.", "Mudheel Grouper",
            "At the first turn all four lean together. The terrace takes a long, confident step and the gardeners laugh at the speed.", 8, SeaJob.Guide, SeaJob.Tow, SeaJob.Relieve));

    static IslandStory[] SaltstepIsles() =>
    [
        Isle("The Saltstep Terraces",9,"Saucepan Rise","Anja, pickle maker",
            "Anja’s whole kitchen is a round pool with a handle of basalt. A walking reef has hooked a foot in it and is dragging the village breakfast toward deep water.", "A salt-pitted pickle fork with one red tine",
            new PostLetter("A gherkin wrapped in a warm tide chart",
                "Grandad said a pickle is ready when it sinks. This one keeps trying to go back to the kitchen. Do you suppose it remembers the bottom?",
                "Nell sends a shallow dish. The pickle settles before lunch."),
            Crossing("wake-pickle-tracks", SeaDuty.Hunt, "The Breakfast Thief",
                "The handle of the village pot leaves a straight scratch beside the reef prints. Anja recognizes the smell of every spill along the route.",
                "Follow the leaking brine to the dragging foot.", "Dillfin Dogfish",
                "The foot belongs to a young reef with a pickle fork between two toes. It moved because it was ticklish.", 7, SeaJob.Track, SeaJob.Bait, SeaJob.DriveOff),
            Landfall("wake-pickle-tine", "Three Good Tines",
                "Anja can lift the fork without hurting the reef if its weight passes onto the salt cradle first. She asks Vara to count the tiny toes aloud.", "Brine Toe Crab",
                "The fork comes free. Anja paints its bent tine red so nobody ever sets it in a nursery pool again.", 7,
                At(LandingAction.Brace, YardSite.West, "Salt cradle", "Brace the foot over the shallow cradle"),
                At(LandingAction.Haul, YardSite.East, "Bent fork", "Draw Anja’s pickle fork out of the brine"),
                At(LandingAction.Guide, YardSite.Stairs, "Pickle maker", "Help Anja climb onto her travelling kitchen")),
            Crossing("wake-pickle-supper", SeaDuty.Convoy, "Lunch Under Way",
                "Children from two walking terraces have come to collect breakfast. One terrace is a fast walker and the other is having a sulk.",
                "Deliver the pickle jars to both moving lunch lines.", "Ladle Gull",
                "The sulking terrace starts again when somebody leaves a jar open. A long marine cucumber claims the last pickle.", 7, SeaJob.Tow, SeaJob.Unload, SeaJob.Relieve),
            Landfall("wake-pickle-seat", "Table for Whoever Comes",
                "Anja wants to leave a table in the empty footprint for people whose islands walk past after dark. The hollow fills from underneath.", "Saltcellar Tortoise",
                "The table rises with the tide on a hollow leg. A late visitor has left a plum stone and two small wet footprints.", 7,
                At(LandingAction.Cut, YardSite.Fallen, "Brine wick", "Trim the long wick under the tabletop"),
                At(LandingAction.Seat, YardSite.East, "Floating foot", "Seat the hollow foot in the pool"),
                At(LandingAction.Turn, YardSite.Crane, "Pantry sign", "Turn the supper sign toward open water"))),
        Isle("The Saltstep Terraces",9,"Bridal Ladder","Gio, travelling registrar",
            "Two villages hold a wedding halfway up a tidal staircase every spring. This year the top half of the stair has departed with both wedding rings in a soap dish.", "Gio’s tideproof buttonhole",
            new PostLetter("Two wedding portraits printed on one biscuit",
                "We forgot to ask the moving stair whether it would marry a second village next spring. Has the harbor ever witnessed a staircase making a promise?",
                "The stair is entered as a witness. It makes its mark in damp plaster."),
            Crossing("wake-bridal-soap", SeaDuty.Salvage, "Something Borrowed",
                "Gio dropped the rings into the dish when the stair lurched. The bride knows which half of the island went where because she was measuring it for garlands.",
                "Recover the soap dish from the departing stair.", "Soapsole",
                "The rings have slipped through its drain holes. An old bath chain rattles in the footwell below.", 7, SeaJob.Sound, SeaJob.Salvage, SeaJob.Track),
            Landfall("wake-bridal-chain", "A Garland of Chains",
                "The bath chain has caught the rings and a bucketful of wedding confetti. Its far end is anchored to the pipe that keeps the upper village alive.", "Bathplug Mole",
                "The rings come back separately, one in each palm. Gio writes their return times in the proper order.", 7,
                At(LandingAction.Brace, YardSite.West, "Water main", "Hold the main off the bath chain"),
                At(LandingAction.Cut, YardSite.East, "Confetti twine", "Cut the soggy twine free"),
                At(LandingAction.Haul, YardSite.Fallen, "Ring chain", "Raise the bath chain with both rings")),
            Crossing("wake-bridal-hour", SeaDuty.Sounding, "The Moving Appointment",
                "The two halves of the staircase meet for one afternoon in twelve. The wedding guests include a grandmother who only travels by rowing backward.",
                "Find the next meeting place for the two villages.", "Vowfin",
                "Gio draws the meeting place on the grandmother’s oar. She reads it over her shoulder and sets out first.", 8, SeaJob.Track, SeaJob.Sound, SeaJob.Relay),
            Landfall("wake-bridal-walk", "Down the Middle",
                "The stairs pass close enough for one narrow bridge. The couple have asked to walk in from opposite ends. Their hats meet above the center rail.", "Buttonhole Wren",
                "The bride pins Gio’s flower to the last bolt before the stairs part. Both villages carry its scent away.", 7,
                At(LandingAction.Seat, YardSite.West, "Bridge hinge", "Seat the hinge at the lower village"),
                At(LandingAction.Brace, YardSite.East, "Second rail", "Hold the rail while the two stairs meet"),
                At(LandingAction.Guide, YardSite.Stairs, "Grandmother", "Walk the grandmother to the middle landing"))),
        Isle("The Saltstep Terraces",9,"Deep Apron","Sol, mud baker",
            "A baker makes insulating bricks from the clay islands leave in their prints. One brick has sprouted feelers in the oven. Sol needs somewhere warm to put it down.", "A still-warm unfired thumb brick",
            new PostLetter("A folded apron with two muddy ties",
                "The first brick has learned to shut the oven door. It has also learned to open the flour cupboard. We have reached an arrangement.",
                "Vara sends a little shelf and the brick’s first set of oven gloves."),
            Landfall("wake-apron-warm", "A Brick with Whiskers",
                "Sol cannot turn off the kiln without killing the other unhatched bricks. The little one hiding in the flue seems as frightened of the oven peel as of the heat.", "Cinder Whisker",
                "Sol carries the first hatchling out in a warm apron. A neat rectangle of soot is missing from the oven wall.", 7,
                At(LandingAction.Brace, YardSite.West, "Flue hood", "Raise the hood to vent excess heat"),
                At(LandingAction.Haul, YardSite.East, "Oven peel", "Hook the old peel away from the nest"),
                At(LandingAction.Guide, YardSite.Stairs, "Mud baker", "Lead Sol out with the warm hatchling")),
            Crossing("wake-apron-clay", SeaDuty.Sounding, "Soft Underneath",
                "Uma thinks the prints release eggs when a mature island rests. Sol knows which print supplied the whiskered brick. It bears his missing boot heel.",
                "Trace the warm clay seam back to its print.", "Bootheel Ray",
                "There are whole islands asleep inside the seam. Sol knots his apron shut and lends Uma his boots.", 7, SeaJob.Sound, SeaJob.Track, SeaJob.Relay),
            Crossing("wake-apron-oven", SeaDuty.Convoy, "An Oven on Wheels",
                "Sol’s oven can hold twelve hatchlings at a time. The gardeners offer to tow it if somebody else carries the chimney. Vara volunteers the mast.",
                "Tow the floating incubator to a sheltered mudflat.", "Peelback Skate",
                "The chimney whistles whenever a brick hatches. Nobody on watch gets much sleep.", 8, SeaJob.Tow, SeaJob.Relieve, SeaJob.Guide),
            Landfall("wake-apron-kiln", "The Open Oven",
                "The nursery needs a wall the hatchlings can leave of their own accord. Sol sets the bricks on their ends with little warm gaps between them.", "Mortar Badger",
                "Three hatchlings head for the sea. A fourth climbs into Sol’s apron. He carries it home and lays a thirteenth place at supper.", 7,
                At(LandingAction.Cut, YardSite.Fallen, "Kiln lacing", "Cut the old iron lacing from the wall"),
                At(LandingAction.Seat, YardSite.West, "Apron stone", "Seat the soft stone below the hatchlings"),
                At(LandingAction.Turn, YardSite.East, "Nursery flap", "Swing the nursery flap toward the mudflat"))),
        Isle("The Saltstep Terraces",9,"Sixth Puddle","Peri, weather reader",
            "Peri reads the sky in six shallow pools. The sixth pool has begun predicting sunshine on dark nights. Her sister says a different sky has learned their address.", "Peri’s pocket sky in a glass button",
            new PostLetter("A cloud caught under a watch glass",
                "We checked the night sky with our pocket button. Three stars are missing from the button. My sister says we can lend it three raindrops.",
                "Lio polishes three round drops into the glass and sends it under a dark cloth."),
            Crossing("wake-puddle-night", SeaDuty.Sounding, "Rain Above the Stars",
                "The sixth pool is reflecting clouds from the coast the island is walking toward. Peri needs two lines of position on the brightest false star.",
                "Sight the reflected sky and mark where the clouds came from.", "Night Gauge",
                "The star is a lantern on her sister’s old rain hut. Peri knows which shutters face home.", 7, SeaJob.Sound, SeaJob.Relay, SeaJob.Track),
            Landfall("wake-puddle-glass", "A Window Underfoot",
                "Wind has rubbed a clear hole through the bottom of the pool. To read its sky without draining it, Peri needs a glass button from the ruined coat house.", "Raincoat Stoat",
                "The button fits. For the first time Peri can watch both sisters standing in the same puddle under different skies.", 7,
                At(LandingAction.Haul, YardSite.Fallen, "Coat drawer", "Haul the soaked drawer from the shaft"),
                At(LandingAction.Seat, YardSite.West, "Glass button", "Seat a clear button in the pool bed"),
                At(LandingAction.Turn, YardSite.East, "Rain shutter", "Turn the shutter to the other sky")),
            Crossing("wake-puddle-runner", SeaDuty.Hunt, "Somebody Else’s Rain",
                "A cloud that fell through the split pool is soaking one fishing boat wherever it goes. Peri has a glass lid large enough to catch the cloud’s reflection.",
                "Track the drifting shower and draw it over the empty pool.", "Umbrella Bill",
                "The fishing captain sends a dry invoice. It is the first piece of dry paper anyone aboard has touched in a week.", 8, SeaJob.Track, SeaJob.Bait, SeaJob.DriveOff),
            Landfall("wake-puddle-hut", "Coast Seen Both Ways",
                "Peri and her sister once shared the rain hut in shifts. They have each been keeping the other’s coat on a peg, despite living three islands apart.", "Peg Rook",
                "Both coats hang over a single door. Peri posts a glass button to Last Light so the crew can see where the hut goes next.", 7,
                At(LandingAction.Brace, YardSite.West, "Hut sill", "Brace the rain hut on its moving foot"),
                At(LandingAction.Seat, YardSite.East, "Window hinge", "Fit the two-sided hinge"),
                At(LandingAction.Guide, YardSite.Stairs, "Weather reader", "Walk Peri to the new rain door")))
    ];
}
